  // Dispatcher already resolved this file as part of a bulk probe: no round trip.\r\n        // A MISS falls through to the scalar path below rather than assuming anything —\r\n        // the fallback can only cost latency, never skip an un-ingested file.\r\n        if (filePath is not null && plan.Resolved is { } cache\r\n            && cache.TryGetValue(filePath, out var hit))\r\n            return plan.IgnoreCompletedFiles ? (hit.Root, false) : hit;\r\n\r\n        Hash128? root = TryResolveFileIdentity(filePath);\r\n        if (root is not { } r) return (null, false);\r\n        if (plan.IgnoreCompletedFiles) return (r, false); // --force: re-observe, still re-mark\r\n        bool done = plan.DecomposerSourceId == default\r\n            ? await plan.Reader.HasSourceCompletedAsync(r, plan.LayerOrder, ct).ConfigureAwait(false)\r\n            : await plan.Reader.HasFileCompletedAsync(\r\n                r, plan.DecomposerSourceId, plan.LayerOrder, ct).ConfigureAwait(false);\r\n        return (r, done);\r\n    }"}, {"id": "c745334e63821514e049-39729", "name": "RunMultiFileSequentialAsync", "repo": "Laplace", "path": "app/Laplace.Substrate/Abstractions/IngestPipeline.cs", "line": 894, "end_line": 1028, "file": "c745334e63821514e049", "kind": "method_declaration", "parse_error": false, "working_tree_changed": false, "calls": [{"name": "stream.FilesAsync", "line": 904}, {"name": "handlerFactory", "line": 907}, {"name": "configFactory", "line": 908}, {"name": "ResolveResumeAsync(resume, source.FilePath, ct)\r\n                .ConfigureAwait", "line": 910}, {"name": "ResolveResumeAsync", "line": 910}, {"name": "Console.Error.WriteLine", "line": 914}, {"name": "Laplace.Ingestion.IngestObservabilityScope.Current.OnFileComposed", "line": 915}, {"name": "BuildSkippedBoundary", "line": 928}, {"name": "Laplace.Ingestion.IngestObservabilityScope.Current.OnFileStarted", "line": 932}, {"name": "TryFileBytes", "line": 933}, {"name": "config.WithMaxInputUnits", "line": 944}, {"nam